//! The shared transaction shape — ported from `@/features/finance/lib/txn`.
//!
//! One definition, because the alternative is each capability inventing its own and the crate
//! carrying six subtly different ideas of what a transaction is. The fields are the ones a statement
//! actually gives you and nothing more: anything richer — category, merchant identity, account type
//! — is DERIVED by a capability that says so, rather than assumed to be present.
use crate::money::{Currency, Money};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// ISO `YYYY-MM-DD`. Normalised at ingest, because comparing dates written three ways is not
    /// analysis, it is guessing.
    pub date: String,
    /// The description exactly as the statement wrote it. Normalisation is a capability's job and is
    /// always reversible to this.
    pub description: String,
    /// NEGATIVE is money leaving the account holder — the one contract ingest normalises to.
    pub amount: Money,
    /// Which account it belongs to. Two accounts can hold the same charge on the same day.
    pub account: String,
}

impl Txn {
    /// Lift a parsed statement row into the analysis shape, attaching the account the file belongs
    /// to and the currency it is denominated in — neither of which a row can know on its own.
    pub fn from_row(row: &crate::statement::Txn, account: &str, currency: Currency) -> Txn {
        Txn {
            date: row.date.clone(),
            description: row.description.clone(),
            amount: Money { minor: row.minor, currency },
            account: account.to_string(),
        }
    }
}

/// Days between two ISO dates. UTC, so a DST boundary cannot make a 30-day month 29.96 days.
///
/// Returns 0 for anything that is not a pair of dates rather than guessing a distance — a bad date
/// producing a plausible gap is how a cadence gets misclassified.
pub fn days_between(a: &str, b: &str) -> i64 {
    let (Some(x), Some(y)) = (
        crate::session::epoch_seconds(&format!("{a}T00:00:00Z")),
        crate::session::epoch_seconds(&format!("{b}T00:00:00Z")),
    ) else {
        return 0;
    };
    (y - x) / 86_400
}

/// `YYYY-MM` — the period most statement analysis groups by.
pub fn month_of(date: &str) -> &str {
    if date.len() >= 7 { &date[..7] } else { date }
}

/// Tokens that appear in descriptions without identifying the merchant.
const NOISE: &[&str] = &[
    "purchase", "payment", "pos", "debit", "credit", "card", "recurring", "autopay", "auto",
    "transaction", "ach", "web", "id", "ref", "the", "inc", "llc", "co", "com", "www", "usa", "us",
];

/// A merchant key: the description reduced to what is STABLE across occurrences.
///
/// A recurring charge rarely writes itself identically twice — statements append dates, store
/// numbers, transaction ids and city names. Matching on the raw description would find no recurrence
/// at all, which is the failure mode that makes a subscription detector look like it works while
/// finding nothing.
///
/// SPLIT FIRST, THEN DISCARD ANY TOKEN THAT CARRIED A DIGIT. Stripping digits before splitting
/// leaves the LETTER FRAGMENTS of an alphanumeric id behind: `AMZN Mktp US*2X4TY1` would reduce to
/// `amzn mktp ty` and `AMZN Mktp US*9KK2P0` to `amzn mktp kk`, so one merchant produces a different
/// key on every occurrence and matches itself never.
///
/// Deliberately crude and DETERMINISTIC. A smarter matcher would need a model, and a model here
/// would mean sending somebody's merchant list somewhere.
pub fn merchant_key(description: &str, words: usize) -> String {
    description
        .to_ascii_lowercase()
        .split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .filter(|w| !w.bytes().any(|b| b.is_ascii_digit()))
        .filter(|w| w.len() > 1)
        .filter(|w| !NOISE.contains(w))
        .take(words)
        .collect::<Vec<_>>()
        .join(" ")
}

/// The default width — three words, which is what the TypeScript uses everywhere it calls this.
pub fn merchant_key_default(description: &str) -> String {
    merchant_key(description, 3)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    /// EVERY VALUE HERE CAME FROM RUNNING `@/features/finance/lib/txn`, not from reading it — the
    /// same discipline the money parity table records, and for the same reason: the first pass of
    /// that port diverged in four places because it was written from a reading.
    #[test]
    fn merchant_key_matches_the_typescript_value_for_value() {
        let cases: &[(&str, &str)] = &[
            ("AMZN Mktp US*2X4TY1", "amzn mktp"),
            ("AMZN Mktp US*9KK2P0", "amzn mktp"),
            ("SQUARE, INC COFFEE", "square coffee"),
            ("NETFLIX.COM", "netflix"),
            ("SAFEWAY #221", "safeway"),
            ("PAYMENT - THANK YOU", "thank you"),
            ("SHELL OIL 4471", "shell oil"),
            ("RENT PAYMENT LANDLORD", "rent landlord"),
            ("TST* CORNER CAFE 09", "tst corner cafe"),
            ("ACH WEB PMT ID 12345 ACME", "pmt acme"),
            ("a", ""),
            ("  ", ""),
            ("USA INC LLC CO", ""),
        ];
        for (input, expected) in cases {
            assert_eq!(merchant_key_default(input), *expected, "merchantKey({input:?})");
        }
    }

    #[test]
    fn one_merchant_gives_one_key_however_the_statement_dresses_it_up() {
        // THE WHOLE POINT. Two Amazon rows with different order ids must collapse to one key, or a
        // subscription detector looks like it works while finding nothing.
        assert_eq!(merchant_key_default("AMZN Mktp US*2X4TY1"), merchant_key_default("AMZN Mktp US*9KK2P0"));
        assert_ne!(merchant_key_default("SAFEWAY #221"), merchant_key_default("SHELL OIL 4471"));
    }

    #[test]
    fn a_digit_bearing_token_is_dropped_whole_rather_than_stripped() {
        // Stripping digits first would leave `ty` and `kk` behind — letter fragments of an id, which
        // differ on every occurrence.
        assert!(!merchant_key_default("AMZN Mktp US*2X4TY1").contains("ty"));
        assert!(!merchant_key_default("STORE 4A7B").contains("a7b"));
        assert_eq!(merchant_key_default("STORE 4A7B"), "store");
    }

    #[test]
    fn the_width_is_a_parameter_and_three_is_the_default() {
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 1), "tst");
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 2), "tst corner");
        assert_eq!(merchant_key_default("TST* CORNER CAFE 09"), merchant_key("TST* CORNER CAFE 09", 3));
    }

    #[test]
    fn days_between_matches_the_typescript_and_signs_correctly() {
        assert_eq!(days_between("2026-01-01", "2026-03-01"), 59);
        assert_eq!(days_between("2026-03-01", "2026-01-01"), -59);
        // A leap day is a real day.
        assert_eq!(days_between("2024-02-28", "2024-03-01"), 2);
        assert_eq!(days_between("2026-02-28", "2026-03-01"), 1);
        assert_eq!(days_between("2026-06-01", "2026-06-01"), 0);
    }

    #[test]
    fn a_date_it_cannot_read_is_zero_rather_than_a_plausible_gap() {
        // A bad date producing a plausible distance is how a cadence gets misclassified, and the
        // wrong cadence misstates annual income by two whole payments.
        assert_eq!(days_between("not-a-date", "2026-03-01"), 0);
        assert_eq!(days_between("2026-13-01", "2026-03-01"), 0);
    }

    #[test]
    fn month_of_is_the_first_seven_characters_and_survives_a_short_string() {
        assert_eq!(month_of("2026-07-15"), "2026-07");
        assert_eq!(month_of("2026-07"), "2026-07");
        assert_eq!(month_of("bad"), "bad");
    }

    #[test]
    fn a_statement_row_lifts_into_the_analysis_shape_with_its_account_and_currency() {
        // Neither is knowable from the row itself: the account comes from which FILE it was in, and
        // the currency from what the account is denominated in.
        let row = crate::statement::Txn {
            date: "2026-06-03".into(),
            description: "SAFEWAY #221".into(),
            minor: -8410,
        };
        let t = Txn::from_row(&row, "chase-credit", Currency::USD);
        assert_eq!(t.account, "chase-credit");
        assert_eq!(t.amount, usd(-8410));
        assert_eq!(t.date, "2026-06-03");
        assert_eq!(t.description, "SAFEWAY #221");
    }
}
